export const CLASSICS_LANGUAGES = Object.keys(CLASSICS_WORKS);

/** Curated classics entry for a language + ref (import metadata). */
export const classicsByRef = (language, ref) =>
  (CLASSICS_WORKS[language] ?? []).find((w) => w.ref === ref) ?? null;

/** Curated shelf as catalog items (pure; local filtering like Aozora). */
export function classicsCatalogItems(language, query) {
  const q = String(query ?? '').trim().toLowerCase();
  return (CLASSICS_WORKS[language] ?? [])
    .filter(
      (w) =>
        !q ||
        w.t.toLowerCase().includes(q) ||
        w.au.toLowerCase().includes(q) ||
        w.d.toLowerCase().includes(q),
    )
    .map((w) => ({
      provider: 'classics',
      ref: w.ref,
      title: w.t,
      author: w.au,
      language,
      source_url: `https://${language}.wikisource.org/wiki/${encodeURIComponent(w.ref.replace(/ /g, '_'))}`,
      license: 'unspecified (varies per work - check the work page)',
      description: w.d,
    }));
}

